// P0 of the super-agent borrow design (docs/decisions/superagent-borrow-design.md §2, §10, §11): the protocol
// contract and the off baseline, checked without a provider and without a consumer.
//
// Every case comes in the shape the design asks for: the contract refuses what it cannot honour (v1, an owner model,
// a stored policy that disagrees, a migration that has not drained), the off position is HEAD's by object identity and
// by generated bytes. §12 records root-decision-v1; a deployment must still name its intent selection explicitly.
import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { cleanupDirs } from '../../packages/profiles/test-support/temp-roots.mjs';
import {
  superagentBorrowConfig, SUPERAGENT_BORROW_DEFAULTS, SUPERAGENT_BORROW_CODES, superagentBorrowCodeList,
  INTENT_SEMANTICS_VALUES, borrowReadiness, assertProtocolSupported, assertBorrowPreconditions, teamPolicyRow,
  policyDecision, assertPolicyCompatible, MIGRATION_PREREQUISITES, migrationCheck, assertMigrationReady,
  ROOT_TOOL_POLICY, TOOL_CAPABILITIES, TOOL_CAPABILITY_DECLARATIONS, capabilityDeclaration, toolCapabilityDecision,
  BORROW_POLICY_VERSION, codes,
} from '../../packages/contracts/index.mjs';
import { teamSchemas, teamSchemasFor, teamSchemasForBorrow, roleTools } from '../../packages/contracts/team-tools.mjs';
import { generate } from '../../packages/profiles/index.mjs';
import { apply as applyTeamProfile } from '../../packages/profiles/team-plugin.mjs';
import { profile } from '../../packages/host/test-support/profile.mjs';
import { ControlStore } from '../../packages/store/index.mjs';
import { OwnershipHandle, TeamManager, acquireOwnership } from '../../packages/host/index.mjs';

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const scenario = path.join(repo, 'verification', 'fixtures', 'superagent-borrow-off-scenario.mjs');
const POSITIONS = [['off', 'off'], ['off', 'on'], ['on', 'off'], ['on', 'on']];
const ROLES = ['root', 'subCoordinator', 'worker', 'verifier'];

test('§2: the switch is off by default, frozen, one position, and refuses what it does not define', () => {
  const defaults = superagentBorrowConfig();
  assert.deepEqual({ ...defaults }, { superagentBorrow: 'off', ownerModel: null, intentSemantics: 'undecided' });
  assert(Object.isFrozen(defaults), 'a protocol switch that can be edited after the mount is not a contract');
  assert.deepEqual(superagentBorrowConfig({}), defaults);
  assert.equal(SUPERAGENT_BORROW_DEFAULTS.superagentBorrow, 'off', 'the product as it is today');
  for (const bad of [
    { superagentBorrow: 'yes' }, { superagentBorrow: true }, { superagentBorrow: 'v1', nope: 1 },
    { ownerModel: { provider: 'p' } }, { ownerModel: { provider: '', model: 'm' } },
    { ownerModel: { provider: 'p', model: 'm', extra: 1 } }, { ownerModel: 'light' },
    { intentSemantics: 'maybe' },
  ]) {
    assert.throws(() => superagentBorrowConfig(bad), error => error?.code === 'INVALID_CONFIG', 'refused: ' + JSON.stringify(bad));
  }
  const named = superagentBorrowConfig({ ownerModel: { provider: 'p', model: 'm' } });
  assert.deepEqual({ ...named.ownerModel }, { provider: 'p', model: 'm' });
  assert(Object.isFrozen(named.ownerModel));
});

test('§12: intent selection is explicit; the recorded root-decision choice does not enable v1', () => {
  // Both historical stances remain parseable, but only root-decision-v1 is the selected v1 semantics.
  // The deployment sentinel undecided must not activate a protocol.
  for (const semantics of INTENT_SEMANTICS_VALUES.filter(value => value !== 'undecided')) {
    const resolved = superagentBorrowConfig({ superagentBorrow: 'v1', intentSemantics: semantics });
    assert.equal(resolved.intentSemantics, semantics);
    const readiness = borrowReadiness(resolved);
    assert(!readiness.blockers.some(blocker => blocker.id === 's1-intent-semantics-undecided'),
      'a recorded value is not undecided: ' + semantics);
    assert.equal(readiness.blockers.some(blocker => blocker.id === 's1-intent-semantics-unsupported'),
      semantics === 'silence-pass-m2b', 'the v1 design selected root-decision-v1, not silence pass');
  }
  const undecided = borrowReadiness(superagentBorrowConfig({ superagentBorrow: 'v1' }));
  assert(undecided.blockers.some(blocker => blocker.id === 's1-intent-semantics-undecided'),
    'with no answer, v1 is blocked instead of silently passing or silently adjudicating');
});

test('§2, §10 P0: v1 and an owner model are refused at start-up, because this build has no consumer for them', () => {
  assert.equal(borrowReadiness(superagentBorrowConfig()).ready, true, 'off has nothing outstanding');
  assert.deepEqual(assertProtocolSupported(superagentBorrowConfig()), borrowReadiness(superagentBorrowConfig()));
  const v1 = superagentBorrowConfig({ superagentBorrow: 'v1', intentSemantics: 'root-decision-v1' });
  assert.throws(() => assertProtocolSupported(v1), error => error?.code === 'PROTOCOL_UNSUPPORTED');
  assert.throws(() => assertProtocolSupported(superagentBorrowConfig({ superagentBorrow: 'v1' })),
    error => error?.code === 'PROTOCOL_UNSUPPORTED');
  const model = superagentBorrowConfig({ ownerModel: { provider: 'p', model: 'm' } });
  assert(borrowReadiness(model).blockers.some(blocker => blocker.id === 'owner-model-not-wired'));
  assert.throws(() => assertProtocolSupported(model), error => error?.code === 'PROTOCOL_UNSUPPORTED');
});

test('§2: v1 is one protocol version and only exists on the four capabilities it was designed against', () => {
  const full = { team: true, guard: true, goalCheck: true, autonomy: 'on', collab: 'on' };
  assert.equal(assertBorrowPreconditions(full), true);
  for (const key of ['team', 'guard', 'goalCheck', 'autonomy', 'collab']) {
    const broken = { ...full, [key]: key === 'autonomy' || key === 'collab' ? 'off' : false };
    assert.throws(() => assertBorrowPreconditions(broken), error => error?.code === 'INVALID_CONFIG', 'missing ' + key);
  }
});

test('§2: the persistent team policy is one row version, and a mismatch is refused rather than reinterpreted', () => {
  const row = teamPolicyRow('team-1', { superagentBorrow: 'v1', activatedAt: '2026-11-01T00:00:00.000Z', migrationRef: 'migration:summary-1' });
  assert.deepEqual({ ...row }, { version: BORROW_POLICY_VERSION, superagentBorrow: 'v1',
    activatedAt: '2026-11-01T00:00:00.000Z', migrationRef: 'migration:summary-1' });
  assert(Object.isFrozen(row));
  assert.throws(() => teamPolicyRow('', { superagentBorrow: 'off', activatedAt: '2026-11-01T00:00:00.000Z', migrationRef: null }),
    error => error?.code === 'INVALID_CONFIG');
  assert.throws(() => teamPolicyRow('team-1', { superagentBorrow: 'off', activatedAt: 'yesterday', migrationRef: null }),
    error => error?.code === 'INVALID_CONFIG');

  // A store that never ran the protocol has no row: off over an old database is not a change (and P0 writes no row).
  assert.deepEqual({ ...policyDecision(null, 'off') }, { decision: 'fresh', reason: 'no-policy-row' });
  assert.deepEqual({ ...policyDecision(row, 'v1') }, { decision: 'match', reason: null });
  for (const [persisted, configured, reason] of [
    [row, 'off', 'configured-protocol-differs-from-store'],
    [{ ...row, version: 2 }, 'v1', 'unknown-policy-version'],
    [{ ...row, superagentBorrow: 'maybe' }, 'v1', 'invalid-stored-protocol'],
    [{ ...row, extra: 1 }, 'v1', 'policy-row-has-unknown-fields'],
    [{ ...row, activatedAt: undefined }, 'v1', 'invalid-policy-metadata'],
    [{ ...row, migrationRef: undefined }, 'v1', 'invalid-policy-metadata'],
    [{ ...row, migrationRef: '' }, 'v1', 'invalid-policy-metadata'],
  ]) {
    const decision = policyDecision(persisted, configured);
    assert.equal(decision.decision, 'mismatch');
    assert.equal(decision.reason, reason);
    assert.throws(() => assertPolicyCompatible(persisted, configured), error => error?.code === 'POLICY_MISMATCH');
  }
});

test('§2, §8: migration needs evidence for every step, and a restart is not one of them', () => {
  const quiescent = { admissionStopped: true, activeExecutions: 0, unknownExecutions: 0, applyingEffects: 0,
    unknownEffects: 0, openIntentWindows: 0, openObjections: 0, migrationSummaryRef: 'migration:summary-1', hostStopped: true };
  const ready = assertMigrationReady(quiescent);
  assert.equal(ready.ready, true);
  assert.deepEqual(ready.checks.map(check => check.id), MIGRATION_PREREQUISITES.map(entry => entry.id));
  const cases = {
    'admission-stopped': { admissionStopped: false },
    'executions-drained': { unknownExecutions: 1 },
    'effects-settled': { applyingEffects: 1 },
    'intent-windows-closed': { openIntentWindows: 1 },
    'objections-decided': { openObjections: 1 },
    'migration-summary-saved': { migrationSummaryRef: null },
    'host-stopped': { hostStopped: false },
  };
  for (const [id, patch] of Object.entries(cases)) {
    const result = migrationCheck({ ...quiescent, ...patch });
    assert.equal(result.ready, false, id + ' must block');
    assert.deepEqual(result.unsatisfied, [id]);
    assert.throws(() => assertMigrationReady({ ...quiescent, ...patch }), error => error?.code === 'MIGRATION_REQUIRED');
  }
  // An observation that did not look is not an observation that found nothing.
  const { openObjections, ...incomplete } = quiescent;
  assert.throws(() => migrationCheck(incomplete), error => error?.code === 'INVALID_CONFIG');
  assert.throws(() => migrationCheck({ ...quiescent, nope: 1 }), error => error?.code === 'INVALID_CONFIG');
});

test('§4.1: every published team tool declares its capabilities, and the root policy decides from them alone', () => {
  for (const [collab, autonomy] of POSITIONS) {
    const schemas = teamSchemasFor(collab, autonomy);
    for (const name of Object.keys(schemas)) {
      const declaration = capabilityDeclaration(name);
      assert(declaration, collab + '/' + autonomy + ': ' + name + ' has no capability declaration');
      assert(declaration.capabilities.every(capability => TOOL_CAPABILITIES.includes(capability)),
        name + ' declares a capability outside the closed vocabulary');
    }
    for (const role of ROLES) {
      for (const name of Object.keys(roleTools(role, collab, autonomy))) {
        assert(capabilityDeclaration(name), role + ' is published ' + name + ' with no capability declaration');
      }
    }
  }
  // Root may read, coordinate and adjudicate - and may not execute, write or reach an opaque tool, whatever it is called.
  for (const name of ['team_read', 'team_message', 'team_thread', 'team_wait', 'team_plan', 'team_member', 'team_goal',
    'team_assume', 'team_decision', 'team_decide']) {
    assert.equal(toolCapabilityDecision(ROOT_TOOL_POLICY, TOOL_CAPABILITY_DECLARATIONS[name]).decision, 'allow', name);
  }
  for (const name of ['team_task', 'team_verify']) {
    const decision = toolCapabilityDecision(ROOT_TOOL_POLICY, TOOL_CAPABILITY_DECLARATIONS[name]);
    assert.equal(decision.decision, 'deny', 'root never produces or verifies a delivery: ' + name);
    assert.equal(decision.reason, 'CAPABILITY_DENIED');
  }
  for (const capabilities of [['bash'], ['opaque'], ['write-local'], ['execute'], []]) {
    assert.equal(toolCapabilityDecision(ROOT_TOOL_POLICY, capabilities).decision, 'deny', JSON.stringify(capabilities));
  }
  assert.equal(toolCapabilityDecision(ROOT_TOOL_POLICY, undefined).reason, 'UNDECLARED_TOOL', 'no declaration is a denial');
  assert.equal(toolCapabilityDecision(ROOT_TOOL_POLICY, ['read-only']).reason, 'UNKNOWN_CAPABILITY');
  assert.equal(capabilityDeclaration('bash'), null, 'a native tool is not declared by this table; P2 declares it at its registration');
  for (const identity of ['__proto__', 'constructor', 'toString', 'hasOwnProperty']) {
    assert.equal(capabilityDeclaration(identity), null, 'inherited property is not a trusted declaration: ' + identity);
  }
  assert(Object.isFrozen(ROOT_TOOL_POLICY) && Object.isFrozen(ROOT_TOOL_POLICY.deny) && Object.isFrozen(ROOT_TOOL_POLICY.allow));
});

test('§2: the borrow off surface is HEAD\'s, by object identity, for every switch position', () => {
  for (const [collab, autonomy] of POSITIONS) {
    // teamSchemasFor builds a fresh surface when a switch is on, so only the default position is identity-checked; the
    // other positions are checked for content, and the delegation itself is what keeps them from being a second copy.
    if (collab === 'off' && autonomy === 'off') {
      assert.equal(teamSchemasForBorrow('off', collab, autonomy), teamSchemas, 'off hands back the published object');
    } else {
      assert.deepEqual(teamSchemasForBorrow('off', collab, autonomy), teamSchemasFor(collab, autonomy),
        'off adds no schema at all (' + collab + '/' + autonomy + ')');
    }
    assert.deepEqual(teamSchemasForBorrow(undefined, collab, autonomy), teamSchemasFor(collab, autonomy));
  }
  assert.equal(teamSchemasForBorrow('off'), teamSchemas, 'and the default position is the published default object');
  assert(teamSchemasForBorrow('v1').team_thread.oneOf.some(b => b.properties.op.const === 'open-resource'));
  assert.throws(() => assertProtocolSupported({ superagentBorrow: 'v1', intentSemantics: 'root-decision-v1' }), error => error?.code === 'PROTOCOL_UNSUPPORTED',
    'publishing schemas is not activation');
  assert.throws(() => teamSchemasForBorrow('maybe'), error => error?.code === 'INVALID_CONFIG');
  assert.throws(() => teamSchemasForBorrow(null), error => error?.code === 'INVALID_CONFIG');
});

test('§10 P0: the contract is importable directly and through the package entry', () => {
  for (const entry of ['superagent-borrow.mjs', 'index.mjs']) {
    const url = new URL('../../packages/contracts/' + entry, import.meta.url).href;
    const out = execFileSync(process.execPath, ['--input-type=module', '-e',
      'import { superagentBorrowConfig } from ' + JSON.stringify(url) + '; console.log(superagentBorrowConfig().superagentBorrow)'],
      { cwd: repo, encoding: 'utf8', windowsHide: true });
    assert.equal(out.trim(), 'off');
  }
});

test('§10 P0: the refusal names are published once, additively, and none of them repeats an existing code', () => {
  const borrow = Object.values(SUPERAGENT_BORROW_CODES).flat();
  assert.deepEqual([...superagentBorrowCodeList], borrow, 'one flat list, built from the grouped table');
  assert.equal(new Set(borrow).size, borrow.length, 'no borrow code is published twice');
  assert.equal(new Set(codes).size, codes.length, 'the published list carries no duplicate at all');
  for (const code of borrow) assert(codes.includes(code), code + ' must appear in the published codes list');
  for (const code of ['PROTOCOL_UNSUPPORTED', 'POLICY_MISMATCH', 'MIGRATION_REQUIRED', 'ROOT_GUARD_UNAVAILABLE',
    'COORDINATE_VIA_ROOT', 'WRONG_THREAD_KIND', 'THREAD_BACKLOG_FULL', 'BATCH_ITEM_TOO_LARGE']) {
    assert(borrow.includes(code), code + ' is named by the design and must be published');
  }
});

test('§2: an unnamed borrow writes nothing into the profile; naming a position this build cannot honour fails the build', () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'borrow-profile-'));
  try {
    const unnamed = generate(path.join(root, 'unnamed'), { team: true, guard: true, goalCheck: true });
    const config = unnamed.entries.at(-1).config;
    for (const key of ['superagentBorrow', 'ownerModel', 'intentSemantics']) {
      assert.equal(Object.hasOwn(config, key), false, key + ' must not appear when the protocol is not configured');
    }
    const named = generate(path.join(root, 'named'), { team: true, guard: true, goalCheck: true, superagentBorrow: 'off' });
    const namedConfig = named.entries.at(-1).config;
    assert.equal(namedConfig.superagentBorrow, 'off');
    assert.equal(namedConfig.ownerModel, null);
    assert.equal(namedConfig.intentSemantics, 'undecided');
    assert.throws(() => generate(path.join(root, 'v1'), { team: true, guard: true, goalCheck: true, superagentBorrow: 'v1',
      autonomy: 'on', collab: 'on' }), error => error?.code === 'PROTOCOL_UNSUPPORTED');
    assert.throws(() => generate(path.join(root, 'v1-partial'), { team: true, guard: true, goalCheck: true, superagentBorrow: 'v1' }),
      error => error?.code === 'PROTOCOL_UNSUPPORTED', 'unsupported takes precedence over missing v1 prerequisites');
    for (const specification of [{ team: false }, { team: true }, { team: true, guard: true }]) {
      for (const request of [{ superagentBorrow: 'v1' }, { ownerModel: { provider: 'p', model: 'm' } }]) {
        const rejectedRoot = path.join(root, 'rejected');
        assert.throws(() => generate(rejectedRoot, { ...specification, ...request }),
          error => error?.code === 'PROTOCOL_UNSUPPORTED');
        assert.equal(fs.existsSync(rejectedRoot), false, 'rejected requests never write a profile');
      }
    }
    assert.throws(() => generate(path.join(root, 'model'), { team: true, guard: true, goalCheck: true,
      ownerModel: { provider: 'p', model: 'm' } }), error => error?.code === 'PROTOCOL_UNSUPPORTED');
    assert.throws(() => generate(path.join(root, 'non-team'), { team: false, superagentBorrow: 'off' }),
      error => error?.code === 'INVALID_CONFIG', 'the protocol is a team-profile option');
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});
